      "overview": "동화 같은 이야기는 이제 끝났다. 로스앤젤레스는 더 이상 예전처럼 히피를 처치하는 스턴트맨을 필요로 하지 않는다. 하지만 할리우드에는 언제나 문제가 생기는 법. 그리고 그 문제들은 클리프처럼 독특하고 (때로는 법의 테두리를 넘나드는) 능력을 지닌 자만이 해결할 수 있다. 생계를 위해 바텐더나 영사 기사로 일하는 시간 외에, 클리프 부스는 해결사로 활동하며 할리우드의 거물들, 때때로 그다지 떳떳하지 못한 이들을 위해 뒷수습에 나선다. 탤런트 에이전트 캐런 크로스비(엘리자베스 데비키)에게서 전화를 받은 클리프는 호기심이 동한다. 캐런은 직접 스턴트를 소화하는 것으로 유명한 TV 슈퍼스타 찰리 피터스(스콧 칸)를 대신해 연락한 것. 찰리 주변 인물들을 만나본 클리프는 더욱 구미가 당기고 호기심을 느낀다. 뭔가 알고 있는 듯한 찰리의 아내 토니(칼라 구지노)부터 프로 미식축구 챔피언에서 스크린 스타로 변신한 로더릭 '핫 로드' 해리슨(야히아 압둘마틴 2세), 도시 곳곳에서 소동을 일으키는 정체불명의 갱스터 베르두스코 형제(맷 그루브와 JB 타데나)까지, 흥미롭지 않을 수 없다. 이제 한때 동화였던 이야기는 범죄극으로 변모한다. 폭력과 야망, 욕망을 한데 섞은 칵테일 같은 이야기. 오직 LA에서만 맛볼 수 있는 일이다.",
