      "overview": "색감이 넘치는 90년대 어린이 TV 쇼 'It's Buddy!'에서는 오렌지색 유니콘 Buddy가 매일 아이들과 함께 노래하고 춤추며 친절과 나눔의 가치를 가르친다. 그런데 이 쇼를 기억하는 사람은 아무도 없고, 출연하는 아이들도 자신이 언제부터 이곳에 있었는지 기억하지 못한다. 어느 날 댄스 파티에 끼지 않겠다던 조시가 흔적도 없이 사라지고, Buddy는 그가 모두가 꿈꾸는 '다이아몬드 시티'로 떠났다고 웃으며 말할 뿐이다. 친구의 갑작스러운 실종에 의문을 품은 프레디는 반짝이는 세트장 너머를 조금씩 엿보기 시작한다. 같은 시각 바깥세상에서는 그레이스의 집에서 아무도 켜지 않은 TV에 낯선 쇼가 흘러나온다. 언제나 즐거워야 하는 이 쇼에서 규칙을 어긴 아이에게는 대체 무슨 일이 벌어지는 것일까?",
