        "overview": "순간적인 스릴을 즐기는 건달 제시 두체크는 어느날 라스베가스에서 남의 차를 타고 달아나 경찰의 추적을 받게 된다. 쫓기는 도중, 순간적으로 경찰을 쏴 살인범으로 지명 수배되자 프랑스 출신의 애인 모니카에게 멕시코로 가서 행복하게 살자고 권유한다. 그러나 모니카는 자기 전공인 건축가로서의 출세욕과 멕시코에서의 생활에 대한 매력 사이에서 망설이게 된다. 제시는 돈놀이업자 베루티에게 꾸어준 돈을 받기 위해 모니카와 함께 외딴 곳에서 밤을 새운다. 다음날 모니카는 신문에 크게 나 있는 제시 사진을 보고서는 자기를 두고 떠나게 하기 위해 경찰에 신고를 한다. 베루티가 돈을 가지고 도착하자 경찰도 도착한다. 베루티가 총을 던져주지만 모니카 없이는 떠날 수 없고 자기의 잘못 때문에 총을 들지 않는다. 경찰은 제시를 쏘아 죽이고 애인 모니카는 제시가 범인이라는 것을 모르고 순수한 사랑을 하게 된 충격과 죄의식에 사로 잡힌다.",
